select max(time)
from t_raw_close_price
where time <= #{time}

mapper.delete:
delete from t_industry_calc
where time = #{time}
and   type = #{type}

mapper.select:
with tmp_a as ( select stockCode, `date`, `last`, clac_expma_5, clac_expma_10, clac_expma_20, clac_expma_37, clac_expma_60 , rank() over (PARTITION by stockCode order by `date` desc) rank_date , rank() over (PARTITION by stockCode order by clac_expma_10/clac_expma_5 desc) rank_10_5 , rank() over (PARTITION by stockCode order by clac_expma_20/clac_expma_5 desc) rank_20_5 , rank() over (PARTITION by stockCode order by clac_expma_37/clac_expma_5 desc) rank_37_5 , rank() over (PARTITION by stockCode order by clac_expma_60/clac_expma_5 desc) rank_60_5 from t_qq_node
where `date` <= #{time}
), tmp_b as ( select t1.* from tmp_a t1 where rank_date = 1 -- where `date` = '2025-11-21' ), tmp_c as ( select stockCode , max(rank_10_5) rank_cnt from tmp_a group by stockCode ) select t5.stockCode, t5.`date`, t5.`last` , round(ratio_b/4, 6) ratioB , round(ratio_s/4, 6) ratioS from ( select t2.* , round(rank_10_5/t3.rank_cnt, 6) * 4 ratio_b
, round(1 - (1+rank_10_5)/t3.rank_cnt, 6) * 4 ratio_s
from tmp_b t2, tmp_c t3 where t2.stockCode = t3.stockCode ) t5 order by ratioB, ratioS

select stockCode, date, last, ratioB, ratioS
from t_qq_node_buy
where date = #{day}


select `date` , stockCode, ratioB , rank_ as rankR
from (
    select *
    from (
        select *
        from (
            select `date` , stockCode, ratioB , rank() over (partition by tqnb.stockCode order by ratioB, `date` desc ) rank_ , count(1) over(partition by stockCode ) * 0.045 rank_limit_
            from t_qq_node_buy tqnb
        ) tt
        where rank_ <= rank_limit_
        and stockCode like '0%'
        union all
        select *
        from (
            select `date` , stockCode, ratioB , rank() over (partition by tqnb.stockCode order by ratioB, `date` desc ) rank_ , count(1) over(partition by stockCode ) * 0.035 rank_limit_
            from t_qq_node_buy tqnb
        ) tt
        where rank_ <= rank_limit_
        and stockCode like '1%'
        union all
        select *
        from (
            select `date` , stockCode, ratioB , rank() over (partition by tqnb.stockCode order by ratioB, `date` desc ) rank_ , count(1) over(partition by stockCode ) * 0.015 rank_limit_
            from t_qq_node_buy tqnb
        ) tt
        where rank_ <= rank_limit_
        and stockCode like '3%'
    ) tt
) tt2

mapper.update:
update t_eastmoney_node
set clac_expma_5 = #{expma5}, clac_expma_10=#{expma10}
where id = #{id}

mapper.select:
select distinct ten.`date`
from t_eastmoney_node ten
where ten.`date` > #{startDate}
order by 1 DESC
limit ${limitCnt}
